/// <summary>
/// update values based on changes to InventLocationIdFrom
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormDataFieldEventHandler(formDataFieldStr(InventTransferOrders, InventTransferTable, InventLocationIdFrom), FormDataFieldEventType::Modified),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void InventLocationIdFrom_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    METInventTransferOrdersForm_EventHandler::updateAutoExtract(sender);
}

/// <summary>
/// update values based on changes to InventLocationIdTo
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormDataFieldEventHandler(formDataFieldStr(InventTransferOrders, InventTransferTable, InventLocationIdTo), FormDataFieldEventType::Modified),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void InventLocationIdTo_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    METInventTransferOrdersForm_EventHandler::updateAutoExtract(sender);
}

    /// <summary>
    /// update auto extract value 
    /// </summary>
    /// <param name="_sender">sender</param>
    public static void updateAutoExtract(FormDataObject _sender)
    {
        FormRun                     formRun;
        InventTransferTable         inventTransferTable;
        FormDataSource              inventTransferTable_ds;
        
        METInventTransferTableExt   inventTransferTableExt;
        FormDataSource              inventTransferTableExt_ds;

        inventTransferTable_ds = _sender.datasource();
        inventTransferTable = inventTransferTable_ds.cursor() as InventTransferTable;

        if(inventTransferTable.InventLocationIdFrom && inventTransferTable.InventLocationIdTo)
        {
            formRun  = inventTransferTable_ds.formRun() as FormRun;
            inventTransferTableExt_ds = formRun.dataSource(formDataSourceStr(InventTransferOrders, METInventTransferTableExt));
            inventTransferTableExt = inventTransferTableExt_ds.cursor() as METInventTransferTableExt;

            inventTransferTableExt.AutoExtract = METInventTransferTableExt::metIsAutoExtract(inventTransferTable.InventLocationIdFrom, inventTransferTable.InventLocationIdTo);
            inventTransferTableExt.setExtractionStatus();
        }
    }

/// <summary>
/// Update PackingQty field as uneditable
/// </summary>
/// <param name="sender">WHSInventTransferLine datasource</param>
/// <param name="e">FormDataSourceEventArgs instance</param>
[FormDataSourceEventHandler(formDataSourceStr(InventTransferOrders, WHSInventTransferLine), FormDataSourceEventType::Initialized),
 SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void WHSInventTransferLine_OnInitialized(FormDataSource sender, FormDataSourceEventArgs e)
{
    sender.object(fieldNum(WHSInventTransferLine, PackingQty)).allowEdit(NoYes::No);
}

    /// <summary>
    /// Transfer Qty modified
    /// </summary>
    /// <param name="sender">FormControl</param>
    /// <param name="e">FormControlEventArgs</param>
    [FormControlEventHandler(formControlStr(InventTransferOrders, InventTransferLine_QtyTransfer), FormControlEventType::Modified)]
    public static void InventTransferLine_QtyTransfer_OnModified(FormControl sender, FormControlEventArgs e)
    {
        FormRun formRun;
        METInventTransferLine   metInventTransferLine;
        InventTransferLine  inventTransferLine;
        FormDataSource  InventTransferLine_DS, METInventTransferLine_DS;

        InventTransferLine_DS = sender.formrun().datasource();
        inventTransferLine = InventTransferLine_DS.cursor() as InventTransferLine;

        if (inventTransferLine)
        {
            formRun  = InventTransferLine_DS.formRun() as FormRun;
            METInventTransferLine_DS = formRun.dataSource(formDataSourceStr(InventTransferOrders, METInventTransferLine));
            metInventTransferLine = METInventTransferLine_DS.cursor() as METInventTransferLine;
            metInventTransferLine.setCaseQtyFields();
            
            InventTransferLine_DS.research(true);            
            METInventTransferLine_DS.research(true);           
        }        
    }

    /// <summary>
    /// Transfer Qty modified
    /// </summary>
    /// <param name="sender">FormControl</param>
    /// <param name="e">FormControlEventArgs</param>
    [FormControlEventHandler(formControlStr(InventTransferOrders, InventTransferLine_PdsCWQtyTransfer), FormControlEventType::Modified)]
    public static void InventTransferLine_PdsCWQtyTransfer_OnModified(FormControl sender, FormControlEventArgs e)
    {
        FormRun formRun;
        METInventTransferLine   metInventTransferLine;
        InventTransferLine  inventTransferLine;
        FormDataSource  InventTransferLine_DS, METInventTransferLine_DS;

        InventTransferLine_DS = sender.formrun().datasource();
        inventTransferLine = InventTransferLine_DS.cursor() as InventTransferLine;

        if (inventTransferLine)
        {
            formRun  = InventTransferLine_DS.formRun() as FormRun;
            METInventTransferLine_DS = formRun.dataSource(formDataSourceStr(InventTransferOrders, METInventTransferLine));
            metInventTransferLine = METInventTransferLine_DS.cursor() as METInventTransferLine;
            metInventTransferLine.setCaseQtyFields();
     
            InventTransferLine_DS.research(true);
            METInventTransferLine_DS.research(true);
        }
    }
